use std::collections::HashMap;


let openai = OpenAI::from_env()?;
let anthropic = Anthropic::from_env()?;


// Specialists from different providers share the `Agent` type.
let routes: HashMap<&str, Agent> = HashMap::from([
    (
        "rust",
        AgentBuilder::new(anthropic.completion(anthropic::CLAUDE_SONNET_5_5))
            .preamble("You are an expert Rust programmer.")
            .build(),
    ),
    (
        "maths",
        AgentBuilder::new(openai.completion(openai::GPT_5_5))
            .preamble("You are a mathematician who explains each step.")
            .build(),
    ),
]);


let router = AgentBuilder::new(openai.completion(openai::GPT_5_MINI))
    .preamble(
        "Classify the user's question. Reply with exactly one word from: rust, maths. \
         No other text.",
    )
    .build();


let question = "How do I use async with Rust?";
let topic = router.prompt(question).await?.output();


let Some(agent) = routes.get(topic.trim()) else {
    anyhow::bail!("no route for {topic:?}");
};
println!("{}", agent.prompt(question).await?.output());

/// One route. The description and examples are embedded; `name` is the key.
#[derive(Embed, Clone, Debug, Default, Serialize, Deserialize, Eq, PartialEq)]
struct Route {
    name: String,
    #[embed]
    description: String,
    #[embed]
    examples: Vec<String>,
}


let embedding_model = OpenAI::from_env()?
    .embedding(openai::TEXT_EMBEDDING_3_SMALL, None)
    .erase();


let routes = vec![
    Route {
        name: "rust".into(),
        description: "Programming and software development in Rust".into(),
        examples: vec![
            "How do I write an async function in Rust?".into(),
            "Why does the borrow checker reject this code?".into(),
        ],
    },
    Route {
        name: "maths".into(),
        description: "Mathematics, calculations and equations".into(),
        examples: vec!["Solve this equation".into(), "What is 15% of 200?".into()],
    },
];


let embeddings = EmbeddingsBuilder::new(embedding_model.clone())
    .documents(routes)?
    .build()
    .await?;
let index = InMemoryVectorStore::from_documents(embeddings).index(embedding_model);


let request = VectorSearchRequest::builder()
    .query("How do I use async with Rust?")
    .samples(1)
    .build();


let route = index
    .top_n::<Route>(request)
    .await?
    .into_iter()
    .next()
    .map_or_else(|| "general".to_owned(), |hit| hit.document.name);
println!("route: {route}");

/// Plan and call tools on the fast model; answer on the strong one.
#[derive(Clone)]
struct FastThenStrong;


impl AgentHook for FastThenStrong {
    fn on_model_select(
        &self,
        context: &HookContext,
        _event: ModelSelection<'_>,
    ) -> ModelSelectionAction {
        // `turn()` is the one-based index of the model call in this run.
        if context.turn() == 1 {
            ModelSelectionAction::select("fast")
        } else {
            ModelSelectionAction::select("strong")
        }
    }
}


let agent = AgentBuilder::named_model("fast", OpenAI::from_env()?.completion(openai::GPT_5_MINI))
    .model_route(
        "strong",
        Anthropic::from_env()?.completion(anthropic::CLAUDE_OPUS_5_5),
    )
    // .tool(search_tool) ...
    .add_hook(FastThenStrong)
    .build();


let answer = agent
    .prompt("Research the question, then write a careful answer.")
    .max_turns(4)
    .await?;
println!("{answer}");

let mut agent = AgentBuilder::named_model("fast", OpenAI::from_env()?.completion(openai::GPT_5_MINI))
    .model_route("strong", OpenAI::from_env()?.completion(openai::GPT_5_5))
    .build();


// One run: start from a registered label, or from a model value.
let hard = agent.prompt("Prove that sqrt(2) is irrational.").using_model("strong").await?;
let other = agent
    .prompt("Say hello.")
    .using_model_value(Anthropic::from_env()?.completion(anthropic::CLAUDE_HAIKU_4_5))
    .await?;


// This agent value from now on: a registered label, or a new model.
agent.set_model_label("strong");
agent.set_model(Anthropic::from_env()?.completion(anthropic::CLAUDE_SONNET_5_5));

use rig::providers::registry;


// e.g. read from a config file
let model_name = "anthropic/claude-sonnet-5-5";
let api_key = std::env::var("ANTHROPIC_API_KEY")?;


let model = registry::connect(model_name, api_key)?;
let agent = AgentBuilder::new(model).preamble("You are a helpful assistant.").build();
println!("{}", agent.prompt("Hello!").await?.output());

