let stored = serde_json::to_string(&reference)?;

use rig::catalog::Catalog;
use rig::providers::registry;


let spec = Catalog::builtin()
    .resolve("openai/gpt-5.5")
    .ok_or_else(|| anyhow::anyhow!("model not in catalog"))?;


println!(
    "{}: {:?} token context, tools: {}",
    spec.display_name, spec.context_window, spec.tools
);
if let Some(pricing) = spec.pricing {
    println!("${} / ${} per million input/output tokens", pricing.input, pricing.output);
}


let model = registry::connect(spec, std::env::var("OPENAI_API_KEY")?)?;
